let GhostBtn = ButtonFlat{height: 44 padding: 14 draw_bg +: {color: #xffffff color_hover: #xf0f4f8 color_down: #xe6ecf3} draw_text +: {color: #x1c2430 color_hover: #x1c2430 color_down: #x1c2430}}

fn depth_name(){
    if depth == "glance" { return "L0 glance" }
    if depth == "expand" { return "L1 expanded" }
    return "L2 app"
}

fn refresh_nav(){
    let s = "Depth: " + depth_name() + "   ·   state: " + view_state
    if archived { s = s + "   ·   Archived (demo)" }
    ui.depth_status.set_text(s)
}

fn set_depth(d){ depth = d sent_demo = false refresh_nav() ui.stage.render() }
fn set_state(s){ view_state = s refresh_nav() ui.stage.render() }
fn do_archive(){ archived = true refresh_nav() ui.stage.render() }
fn do_undo(){ archived = false sent_demo = false refresh_nav() ui.stage.render() }
fn on_field(t){ reply_text = t }
fn do_send(){ sent_demo = true ui.stage.render() }

fn boot(){ refresh_nav() ui.stage.render() }

start_timeout(0.05, || boot())

